+  if (need_tie && num_equal > TopK) {
+    exact_topk_rescan<TopK, kBlockSize>(scores, output, length, _smem);
+    return;
+  }
+
   done = false;
 #pragma unroll
   for (uint32_t v = 0; v < VECS_PER_THREAD && !done; v++) {

